base.r/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_dynamodb_table" "t" {
  name     = "orders"
  hash_key = "id"
}
resource "aws_sqs_queue" "q" {
  name = "q"
  lifecycle {
    replace_triggered_by = [aws_dynamodb_table.t.name]
  }
}

